sty=Path('/usr/share/texlive/texmf-dist/tex/latex/quran/quran.sty').read_text()
names_line=re.search(r'\\def\\@@surahname\[#1\]\{%\s*\\ifcase#1 \{\}(.*?)\\else',sty,re.S).group(1)
names=[x.strip() for x in names_line.split('\\or')[1:]]
vers_line=re.search(r'\\def\\qt@getversenum#1\{%\s*\\ifcase#1(.*?)\\else',sty,re.S).group(1)
vers=[int(x.strip()) for x in vers_line.split('\\or')[1:] if x.strip().isdigit()]
assert len(names)==114 and len(vers)==114
