# ---------- GEOGRAPHY from local country datasets ----------
ar=Locale('ar')
region_ar={'Africa':'أفريقيا','Americas':'الأمريكيتان','Asia':'آسيا','Europe':'أوروبا','Oceania':'أوقيانوسيا','Polar':'المنطقة القطبية'}
records=[]
for c in list(pycountry.countries):
    try:
        info=CountryInfo(c.name).info()
    except Exception:
        try: info=CountryInfo(c.official_name).info()
        except Exception: continue
    code=c.alpha_2
    name_ar=ar.territories.get(code)
    if not name_ar or not info.get('region') or not info.get('callingCodes') or not info.get('currencies'): continue
    tld=(info.get('tld') or [None])[0]; alpha3=info.get('ISO',{}).get('alpha3') or c.alpha_3
    if not tld or not alpha3: continue
    records.append({'ar':name_ar,'region':region_ar.get(info['region'],info['region']),'currency':info['currencies'][0],'calling':str(info['callingCodes'][0]),'tld':tld,'alpha3':alpha3,'borders':len(info.get('borders') or [])})
records=sorted(records,key=lambda x:x['ar'])
# Use familiar countries for the easy tier; harder tiers ask harder properties of the same countries.
common_codes=['SA','EG','AE','QA','KW','BH','OM','JO','IQ','SY','LB','MA','DZ','TN','LY','SD','TR','IR','PK','IN','CN','JP','KR','ID','MY','US','CA','MX','BR','AR','GB','FR','DE','IT','ES','PT','NL','BE','CH','AT','RU','UA','GR','SE','NO','DK','AU','NZ','ZA','NG']
by_name={r['ar']:r for r in records}
by_code={}
for code in common_codes:
    ar_name=ar.territories.get(code)
    if ar_name in by_name: by_code[code]=by_name[ar_name]
sample=[by_code[c] for c in common_codes if c in by_code]
if len(sample)<50:
    used={x['ar'] for x in sample}
    sample += [r for r in records if r['ar'] not in used][:50-len(sample)]
sample=sample[:50]
for r in sample: bank.append(q('جغرافيا',100,f'في أي قارة أو منطقة جغرافية تقع {r["ar"]}؟',r['region'],source='country-dataset'))
for r in sample: bank.append(q('جغرافيا',200,f'ما رمز العملة المستخدم في {r["ar"]} وفق معيار ISO؟',r['currency'],source='country-dataset'))
for r in sample: bank.append(q('جغرافيا',300,f'ما مفتاح الاتصال الدولي لدولة {r["ar"]}؟','+'+r['calling'],source='country-dataset'))
for r in sample: bank.append(q('جغرافيا',400,f'كم دولة تحد {r["ar"]} بريًا بحسب بيانات الحدود؟',r['borders'],source='country-dataset'))
for r in sample: bank.append(q('جغرافيا',500,f'ما الرمز الدولي الثلاثي ISO لدولة {r["ar"]}؟',r['alpha3'],source='country-dataset'))

