# Validate exact distribution, normalize IDs.
assert len(bank)==1500, len(bank)
seen=set()
for item in bank:
    key=(item['category_id'],item['question'])
    if key in seen: raise ValueError(f'duplicate: {key}')
    seen.add(key)
    digest=hashlib.sha1((item['category_id']+'|'+item['question']).encode()).hexdigest()[:12]
    item['id']=f"{item['category_id']}-{item['points']}-{digest}"
    item['game_id']='family-challenge'; item['media_type']='none'; item['media_path']=None; item['media_alt']=''; item['active']=True

for cat in CAT_IDS:
    subset=[x for x in bank if x['category']==cat]
    assert len(subset)==250,(cat,len(subset))
    for pts in POINTS:
        n=sum(1 for x in subset if x['points']==pts)
        assert n==50,(cat,pts,n)

OUT.write_text(json.dumps(bank,ensure_ascii=False,indent=2))
print('WROTE',OUT,'questions',len(bank))
for cat in CAT_IDS:
    print(cat,{p:sum(1 for x in bank if x['category']==cat and x['points']==p) for p in POINTS})
